content.css:
.sensitivity-tornado-root {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
}
.sensitivity-tornado-root svg {
  shape-rendering: geometricPrecision;
}
/* ── Axes ── */
.st-axis .tick line {
  stroke: #d0d0d0;
  stroke-width: 0.5;
}
.st-axis .tick text {
  fill: #666;
  font-size: 11px;
}
.st-axis .domain {
  stroke: #aaa;
  stroke-width: 1;
}
.st-axis-label {
  fill: #444;
  font-size: 12px;
  font-weight: 600;
}
.st-param-label {
  fill: #333;
  font-size: 11px;
  font-weight: 600;
}
/* ── Bars ── */
.st-bar {
  cursor: pointer;
  transition: opacity 0.15s ease;
}
.st-bar:hover {
  filter: brightness(1.12);
  stroke: #333;
  stroke-width: 1;
}
.st-bar.dimmed {
  opacity: 0.25;
}
/* ── Data labels ── */
.st-data-label {
  font-size: 9px;
  fill: #555;
  pointer-events: none;
}
/* ── Baseline ── */
.st-baseline {
  stroke-dasharray: none;
}
.st-baseline-label {
  font-size: 10px;
  font-weight: 600;
}
/* ── Grid ── */
.st-grid-line {
  stroke: #e8e8e8;
  stroke-width: 0.5;
  stroke-dasharray: 3 3;
}
/* ── Legend ── */
.st-legend {
  font-size: 11px;
  fill: #555;
}
/* ── Landing page ── */
.st-landing {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  color: #888;
  font-size: 14px;
  text-align: center;
  padding: 24px;
  box-sizing: border-box;
}
/* ── Empty data message ── */
.st-empty {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  color: #94a3b8;
  font-size: 12px;
  text-align: center;
  padding: 20px 24px 28px 24px;
  box-sizing: border-box;
  letter-spacing: 0.2px;
}
/* ── Chart container (flex row: SVG + insight panel side-by-side) ── */
.st-chart-container {
  display: flex;
  flex-direction: row;
  width: 100%;
  height: 100%;
}
.st-chart-container svg {
  flex: 1 1 auto;
  min-width: 0;
}
/* ── Insight Panel (flex sidebar, not absolute) ── */
.st-insight-panel {
  display: none;
  width: 200px;
  min-width: 200px;
  flex: 0 0 200px;
  border-left: 1px solid #e0e0e0;
  background: rgba(255, 255, 255, 0.95);
  padding: 12px;
  box-sizing: border-box;
  font-size: 11px;
  overflow-y: auto;
  overflow-x: hidden;
}
.st-insight-title {
  font-weight: 700;
  font-size: 13px;
  color: #333;
  margin-bottom: 8px;
  padding-bottom: 6px;
  border-bottom: 2px solid #E8612A;
}
.st-insight-collapse-row {
  display: flex;
  justify-content: flex-end;
  margin: -4px -4px 2px 0;
}
.st-insight-collapse-btn {
  font-size: 11px;
  color: #888;
  cursor: pointer;
  user-select: none;
  padding: 2px 6px;
  border-radius: 3px;
  line-height: 1;
  transition: background 0.12s ease, color 0.12s ease;
}
.st-insight-collapse-btn:hover {
  background: rgba(232, 97, 42, 0.12);
  color: #E8612A;
}
/* Thin strip shown when the panel is collapsed (click to re-expand) */
.st-insight-strip {
  display: none;
  flex: 0 0 22px;
  width: 22px;
  min-width: 22px;
  border-left: 1px solid #e0e0e0;
  background: rgba(255, 255, 255, 0);
  align-items: flex-start;
  justify-content: center;
  padding-top: 8px;
  cursor: pointer;
  transition: background 0.12s ease;
}
.st-insight-strip:hover {
  background: rgba(232, 97, 42, 0.08);
}
.st-insight-strip-arrow {
  font-size: 11px;
  color: #888;
  font-weight: 700;
  user-select: none;
}
.st-insight-strip:hover .st-insight-strip-arrow {
  color: #E8612A;
}
.st-insight-row {
  display: flex;
  justify-content: space-between;
  padding: 3px 0;
}
.st-insight-label {
  color: #666;
}
.st-insight-value {
  font-weight: 600;
  color: #333;
}
.st-insight-bars {
  margin-top: 10px;
  padding-top: 8px;
  border-top: 1px solid #e0e0e0;
}
.st-insight-bar-title {
  font-weight: 600;
  color: #333;
  margin-bottom: 6px;
}
.st-insight-bar-item {
  margin-bottom: 4px;
}
.st-insight-bar-name {
  font-size: 10px;
  color: #666;
  margin-bottom: 1px;
}
.st-insight-bar-track {
  height: 8px;
  background: #e0e0e0;
  border-radius: 4px;
  overflow: hidden;
}
.st-insight-bar-fill {
  height: 100%;
  background: linear-gradient(90deg, #e74c3c, #E8612A);
  border-radius: 4px;
}
/* ── Smart Insights callouts ── */
.st-smart-insights {
  margin-top: 12px;
  padding-top: 8px;
  border-top: 1px solid #e0e0e0;
}
.st-callout {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  padding: 6px 8px;
  margin-top: 6px;
  font-size: 10.5px;
  line-height: 1.35;
  border-radius: 4px;
  border-left: 3px solid transparent;
}
.st-callout-icon {
  flex-shrink: 0;
  font-weight: 700;
  font-size: 11px;
  width: 12px;
  text-align: center;
  line-height: 1.35;
}
.st-callout-text {
  color: #333;
}
.st-callout--lever {
  background: rgba(232, 97, 42, 0.08);
  border-left-color: #E8612A;
}
.st-callout--lever .st-callout-icon {
  color: #E8612A;
}
.st-callout--bottleneck {
  background: rgba(231, 76, 60, 0.08);
  border-left-color: #e74c3c;
}
.st-callout--bottleneck .st-callout-icon {
  color: #e74c3c;
}
.st-callout--non-factor {
  background: rgba(127, 140, 141, 0.1);
  border-left-color: #95a5a6;
}
.st-callout--non-factor .st-callout-icon {
  color: #7f8c8d;
}
/* ── License Badge & Watermark ── */
.bfusion-license-badge-wrap {
  position: absolute;
  bottom: 4px;
  left: 8px;
  z-index: 20;
  pointer-events: none;
}
.bfusion-license-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 10px;
  border-radius: 4px;
  font-size: 9px;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  line-height: 1.3;
  pointer-events: auto;
  max-width: 380px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge--valid {
  background: rgba(5, 150, 105, 0.08);
  border: 1px solid rgba(5, 150, 105, 0.25);
  color: #059669;
}
.bfusion-license-badge--invalid {
  background: rgba(220, 38, 38, 0.06);
  border: 1px solid rgba(220, 38, 38, 0.2);
  color: #DC2626;
}
.bfusion-license-badge__icon {
  font-size: 11px;
  flex-shrink: 0;
}
.bfusion-license-badge__text {
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge__text strong {
  font-weight: 600;
}
.bfusion-watermark {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 15;
  pointer-events: none;
  display: flex;
  align-items: center;
  justify-content: center;
  background: repeating-linear-gradient(-45deg, transparent, transparent 120px, rgba(220, 38, 38, 0.03) 120px, rgba(220, 38, 38, 0.03) 122px);
}
.bfusion-watermark__content {
  text-align: center;
  opacity: 0.18;
  user-select: none;
  transform: rotate(-18deg);
}
.bfusion-watermark__title {
  font-size: 56px;
  font-weight: 900;
  color: #DC2626;
  letter-spacing: 12px;
  line-height: 1;
  font-family: "Segoe UI", sans-serif;
}
.bfusion-watermark__subtitle {
  font-size: 16px;
  font-weight: 600;
  color: #DC2626;
  margin-top: 6px;
  letter-spacing: 3px;
  text-transform: uppercase;
  font-family: "Segoe UI", sans-serif;
}
.bfusion-watermark__link {
  font-size: 11px;
  color: #9CA3AF;
  margin-top: 12px;
  font-family: "Segoe UI", sans-serif;
}
